code=r'''
import numpy as np, scipy.special as sp
RES=np.array([83,88,222,254,444,495,506,601]); KEEP=np.setdiff1d(np.arange(768),RES)
def gelu(x): return 0.5*x*(1+sp.erf(x/np.sqrt(2)))
def LN(u):
    m=u.mean(-1,keepdims=True); v=((u-m)**2).mean(-1,keepdims=True); return (u-m)/np.sqrt(v+1e-12)
def pool_z(M9, C9, c, mu9):
    return LN(c*(M9-mu9)+C9)
def anchor_dirs(Za):
    A=Za.copy(); A[:,RES]=0
    return A/np.linalg.norm(A,axis=1,keepdims=True)/np.sqrt(768)
def feats(Z, Wd): return gelu(Z@Wd.T)
def pivchol(K, k):
    n=K.shape[0]; d=np.diag(K).copy(); L=np.zeros((n,k)); piv=[]
    for i in range(k):
        j=int(np.argmax(d)); piv.append(j)
        l=(K[:,j]-L[:,:i]@L[j,:i])/np.sqrt(max(d[j],1e-12)); L[:,i]=l; d=d-l**2; d[piv]=-np.inf
    return np.array(piv)
def fit(Phi, Lin, Y, Kaa, lam, c0, jitter=1e-6):
    X=np.concatenate([Phi,Lin],1); mu=X.mean(0); Xc=X-X.mean(0); Ym=Y.mean(0); Yc=Y-Ym
    na=Phi.shape[1]; nl=Lin.shape[1]
    R=np.zeros((na+nl,na+nl)); R[:na,:na]=Kaa+jitter*np.trace(Kaa)/na*np.eye(na); R[na:,na:]=np.eye(nl)/c0
    coef=np.linalg.solve(Xc.T@Xc+lam*R, Xc.T@Yc)
    b=Ym-mu@coef
    return coef, b
'''
open('poolfit.py','w').write(code)
import sys; sys.path.insert(0,'.')
from poolfit import *
from lib import labels, folds
y=labels(); Y=np.eye(8)[y]
F=np.load('feats_seq1024.npz'); M9=F['mean_hidden_L9'].astype(np.float64); C9=F['cls_hidden_L9'].astype(np.float64); M0=F['mean_hidden_L0'].astype(np.float64)
mu9=M9.mean(0)
Z=pool_z(M9,C9,20.0,mu9)
print('zRES mag', np.abs(Z[:,RES]).mean(), 'KEEP', np.abs(Z[:,KEEP]).mean())
L0=M0-M0.mean(0); L0/=np.sqrt((L0**2).sum(1).mean())
def cv(na, lam, c0, k=10, seeds=(0,1), lin=L0):
    accs=[]
    for s in seeds:
        f=folds(y,k,s); S=np.zeros((len(y),8))
        for i in range(k):
            tr=f!=i; te=f==i
            Ztr=Z[tr]; Kc=gelu(Ztr@anchor_dirs(Ztr).T)  # GELU(cos) among train
            piv=pivchol(Kc, na); Wd=anchor_dirs(Ztr[piv])
            Ptr=feats(Ztr,Wd); Kaa=Ptr[piv]
            coef,b=fit(Ptr, lin[tr], Y[tr], (Kaa+Kaa.T)/2, lam, c0)
            S[te]=np.concatenate([feats(Z[te],Wd),lin[te]],1)@coef+b
        accs.append((S.argmax(1)==y).mean())
    return round(float(np.mean(accs)),4)
